  ['id'=>'grand',   'title'=>'Grand Sponsors',       'size'=>'lg','slots'=>4,'cta'=>'Become a Grand Sponsor',        'tag'=>'Partners who make UDGAM 2K26 shine brighter.',           'sponsors'=>[]],
