<style>
:root{--navy:#17283a;--cream:#f8eddb;--gold:#f3c986;--bg:#0a1322;--s1:#0e1a30;--pk:#ff9ec4;--pk2:#ff5f9e;--cy:#37d7ff;--vi:#8b5cf6;--tx:#fbf1f4;--mu:#a9b5cf;--ln:rgba(255,170,205,.22);
--fd:'Cinzel Decorative','Cormorant Garamond',Georgia,serif;--fb:'Inter','Segoe UI',Arial,sans-serif;--fs:'Playfair Display','Bodoni Moda',Georgia,serif}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth}
html,body{margin:0;background:var(--bg);color:var(--tx);font-family:var(--fb);overflow-x:hidden}
img{display:block;max-width:100%;height:auto}a{color:inherit}
:focus-visible{outline:2px solid var(--gold);outline-offset:3px}
.w{width:min(1180px,100% - 32px);margin-inline:auto}
.kick{font:600 11px/1 var(--fb);letter-spacing:.28em;text-transform:uppercase;color:var(--pk);margin:0 0 14px}
.script{font:italic 500 clamp(1.05rem,2.3vw,1.5rem)/1.6 var(--fs);letter-spacing:.06em;color:var(--gold);margin:0;text-shadow:0 2px 14px rgba(10,19,34,.65),0 0 24px rgba(255,170,120,.3)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:14px 26px;border-radius:999px;font:700 12px/1 var(--fd);letter-spacing:.16em;text-transform:uppercase;text-decoration:none;border:1px solid var(--ln);background:rgba(255,255,255,.06);color:var(--tx);cursor:pointer;transition:transform .25s,box-shadow .25s,background .25s}
.btn:hover{transform:translateY(-3px);background:rgba(255,255,255,.12)}
.btn.p{background:linear-gradient(90deg,var(--pk2),var(--gold));color:#2a0f1c;border-color:transparent;box-shadow:0 10px 30px rgba(255,95,158,.3)}
.btn.p:hover{box-shadow:0 14px 40px rgba(255,95,158,.5)}
/* reveal */
.js .rv{opacity:0;transform:translateY(28px) scale(.97);transition:opacity .9s ease,transform .9s cubic-bezier(.2,.9,.3,1);transition-delay:var(--d,0s)}
.js .rv.in{opacity:1;transform:none}
/* progress vine + petal canvas */
#prog{position:fixed;z-index:120;top:0;left:0;height:3px;width:100%;transform-origin:0 50%;transform:scaleX(0);background:linear-gradient(90deg,var(--vi),var(--pk2),var(--gold));box-shadow:0 0 12px var(--pk2)}
#petalfx{position:fixed;inset:0;width:100%;height:100%;z-index:0;pointer-events:none}
main,footer{position:relative;z-index:1}
.brn{position:fixed;top:0;z-index:0;pointer-events:none;opacity:0;transition:opacity .7s;will-change:transform;filter:drop-shadow(0 6px 18px rgba(255,120,170,.25))}
.brn.on{opacity:.9}
.brn.l{left:0;width:min(46vw,520px);aspect-ratio:494/128;background:url(data:image/webp;base64,) 0 0/100% 100% no-repeat;-webkit-mask-image:linear-gradient(90deg,#000 55%,transparent),linear-gradient(180deg,#000 45%,transparent 96%);mask-image:linear-gradient(90deg,#000 55%,transparent),linear-gradient(180deg,#000 45%,transparent 96%);-webkit-mask-composite:source-in;mask-composite:intersect;transform-origin:0 0;animation:swL 9s ease-in-out infinite}
.brn.r{right:0;width:min(34vw,380px);aspect-ratio:363/271;background:url(data:image/webp;base64,) 0 0/100% 100% no-repeat;transform-origin:100% 0;animation:swR 11s ease-in-out infinite}
@keyframes swL{50%{transform:rotate(1.2deg)}}@keyframes swR{50%{transform:rotate(-1.5deg)}}
.bokeh{position:fixed;inset:0;z-index:0;pointer-events:none;opacity:0;transition:opacity .7s;background:radial-gradient(ellipse 50% 40% at 8% 6%,rgba(255,120,170,.16),transparent 70%),radial-gradient(ellipse 45% 38% at 94% 10%,rgba(255,140,190,.14),transparent 70%),radial-gradient(ellipse 70% 30% at 50% 108%,rgba(255,110,160,.12),transparent 70%)}
.bokeh.on{opacity:1}
/* nav */
.nav{position:fixed;z-index:100;top:0;left:0;right:0;padding:12px 0;border-bottom:1px solid transparent;background:rgba(10,19,34,.2);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);transition:background .3s,border-color .3s;animation:drop .9s ease both}
@keyframes drop{from{transform:translateY(-100%);opacity:0}}
.nav.sc{background:rgba(10,19,34,.88);border-color:var(--ln)}
.nav .w{display:flex;align-items:center;gap:14px;justify-content:space-between}
.brand{font:700 16px/1 var(--fd);letter-spacing:.16em;text-decoration:none;white-space:nowrap}.brand b{color:var(--pk)}
.links{display:flex;gap:2px;align-items:center}
.links a{position:relative;padding:10px 11px;font:600 11px/1 var(--fb);letter-spacing:.1em;text-transform:uppercase;text-decoration:none;color:var(--mu);transition:color .2s}
.links a:hover,.links a.on{color:#fff}
.links a.on::after{content:'';position:absolute;left:11px;right:11px;bottom:2px;height:2px;border-radius:2px;background:linear-gradient(90deg,var(--pk2),var(--gold))}
.nav .btn{padding:11px 18px;font-size:11px}
.burger{display:none;width:42px;height:42px;border-radius:12px;border:1px solid var(--ln);background:rgba(255,255,255,.06);color:#fff;font-size:20px;cursor:pointer}
.links .btn.mob{display:none}
@media(max-width:1020px){.links{display:none;position:absolute;top:100%;left:0;right:0;flex-direction:column;align-items:stretch;padding:12px 16px 18px;background:rgba(10,19,34,.97);border-bottom:1px solid var(--ln)}
.links.open{display:flex}.links a{padding:15px 10px;font-size:12px}.links a.on::after{display:none}.burger{display:block}.nav .btn.rg{display:none}.links .btn.mob{display:inline-flex;margin-top:8px}}
/* hero */
.hero{position:relative;min-height:100vh;min-height:100svh;display:grid;place-items:center;text-align:center;padding:130px 0 90px;overflow:hidden;isolation:isolate}
.hero-bg{position:absolute;inset:-5% 0;z-index:-3;overflow:hidden}
.stage{container-type:inline-size;position:absolute;left:50%;top:50%;width:max(100%,calc(var(--hh,110svh)*1.78));aspect-ratio:16/9;translate:-50% -50%}
@media(max-aspect-ratio:1/1){.stage{translate:-31% -50%}}
/* layered, living dragon: same artwork, masked per body part, each moving differently */
.layer,.base{position:absolute;inset:0;background:url("data:image/svg+xml;charset=utf-8,%3Csvg xmlns='http://www.w3.org/2000/svg' xmlns:xlink='http://www.w3.org/1999/xlink' viewBox='0 0 2400 1350' preserveAspectRatio='none'%3E%3Cimage width='2400' height='1350' preserveAspectRatio='none' xlink:href='data:image/jpeg;base64,'/%3E%3C/svg%3E") 0 0/100% 100% no-repeat}
/* hero tagline baked into the artwork area — static */
.tag{position:absolute;left:44.9%;top:17.6%;width:19.8%;aspect-ratio:285/112;overflow:visible;pointer-events:none}
.tag text{font-family:'Mrs Saint Delafield','Allison','Snell Roundhand',cursive;fill:#f7dbe8;stroke:#f7dbe8;stroke-width:.55;paint-order:stroke;filter:drop-shadow(0 0 5px rgba(255,185,215,.6)) drop-shadow(0 0 14px rgba(255,140,190,.35))}
/* static clean background under the dragon (so nothing ghosts when it moves) */
.plate{position:absolute;inset:0;background:url(data:image/jpeg;base64,) 0 0/100% 100% no-repeat;-webkit-mask-image:url(data:image/png;base64,);mask-image:url(data:image/png;base64,);-webkit-mask-size:100% 100%;mask-size:100% 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat}
/* 3D dragon: 3 depth parts. Body breathes+turns in perspective, head and tail move on top of it. Nothing else moves. */
.dmove,.dp{position:absolute;inset:0;pointer-events:none;backface-visibility:hidden;will-change:transform}
.dmove{transform-origin:17% 58%;animation:bodyM 10s ease-in-out infinite}
.dp.h{transform-origin:22.5% 38%;animation:headM 7s ease-in-out infinite}
.dp.t{transform-origin:27% 62%;animation:tailM 5.2s ease-in-out infinite}
.dbody{-webkit-mask-image:url(data:image/png;base64,);mask-image:url(data:image/png;base64,);-webkit-mask-size:100% 100%;mask-size:100% 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat}.dhead{-webkit-mask-image:url(data:image/png;base64,);mask-image:url(data:image/png;base64,);-webkit-mask-size:100% 100%;mask-size:100% 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat}.dtail{-webkit-mask-image:url(data:image/png;base64,);mask-image:url(data:image/png;base64,);-webkit-mask-size:100% 100%;mask-size:100% 100%;-webkit-mask-repeat:no-repeat;mask-repeat:no-repeat}
@keyframes bodyM{0%,100%{transform:perspective(1500px) rotateY(-3.2deg) rotateZ(-.35deg) scale(1) translate3d(0,0,0)}50%{transform:perspective(1500px) rotateY(3.4deg) rotateZ(.45deg) scale(1.016) translate3d(.3%,-.9%,0)}}
@keyframes headM{0%,100%{transform:perspective(1300px) rotateY(-6deg) rotateX(1.5deg) rotateZ(-1.8deg) translate3d(-.2%,.3%,0)}50%{transform:perspective(1300px) rotateY(6.5deg) rotateX(-1.5deg) rotateZ(2.6deg) scale(1.012) translate3d(.6%,-.8%,0)}}
@keyframes tailM{0%,100%{transform:perspective(1200px) rotateY(-5deg) rotateZ(-4.5deg) translate3d(-.2%,.3%,0)}50%{transform:perspective(1200px) rotateY(6deg) rotateZ(5deg) translate3d(.5%,-.4%,0)}}
.eye{position:absolute;left:32.4%;top:29.3%;width:1.7%;aspect-ratio:1;translate:-50% -50%;border-radius:50%;mix-blend-mode:screen;background:radial-gradient(circle,rgba(255,240,190,.95),rgba(255,120,170,.55) 40%,transparent 70%);animation:eye 6s ease-in-out infinite}
@keyframes eye{0%,100%{opacity:.2;scale:.7}40%,60%{opacity:1;scale:1.15}48%{opacity:.1;scale:.4}}
.aura{position:absolute;left:4%;top:8%;width:36%;height:62%;mix-blend-mode:screen;background:radial-gradient(ellipse,rgba(255,170,215,.4),transparent 66%);animation:aura 5s ease-in-out infinite}
@keyframes aura{0%,100%{opacity:.15}50%{opacity:.8}}
.mist{position:absolute;left:36.5%;top:37%;width:4%;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.75),rgba(255,190,220,.35) 45%,transparent 70%);filter:blur(3px);opacity:0;animation:mist 6s ease-out infinite;animation-delay:var(--d)}
@keyframes mist{0%{opacity:0;transform:translate(0,0) scale(.3)}15%{opacity:.85}100%{opacity:0;transform:translate(330%,-240%) scale(2.6)}}
.sp{position:absolute;left:var(--x);top:var(--y);width:var(--s);aspect-ratio:1;border-radius:50%;background:radial-gradient(circle,#fff,rgba(255,215,230,.9) 35%,transparent 70%);box-shadow:0 0 10px 2px rgba(255,190,220,.8);opacity:0;animation:tw var(--t) ease-in-out infinite;animation-delay:var(--d)}
@keyframes tw{0%{opacity:0;transform:translate(0,0) scale(.3)}25%{opacity:1;transform:translate(.5vw,-.6vw) scale(1)}100%{opacity:0;transform:translate(2vw,-3.5vw) scale(.2)}}
.hero::before{content:'';position:absolute;inset:0;z-index:-2;background:linear-gradient(180deg,rgba(10,19,34,.68),rgba(10,19,34,.18) 38%,rgba(10,19,34,.42) 72%,var(--bg))}
.sunrise{position:absolute;z-index:-1;left:50%;top:44%;width:min(90vw,820px);aspect-ratio:1;translate:-50% -50%;border-radius:50%;background:radial-gradient(circle,rgba(255,190,140,.35),rgba(255,95,158,.16) 45%,transparent 70%);animation:breathe 7s ease-in-out infinite}
@keyframes breathe{50%{scale:1.12;opacity:.65}}
.hero-in{display:flex;flex-direction:column;align-items:center;gap:16px}
.hero .logo{width:clamp(170px,26vw,260px);filter:drop-shadow(0 10px 30px rgba(0,0,0,.45));animation:lsway 7s ease-in-out infinite;transform-origin:50% 90%}
@keyframes lsway{0%,100%{transform:translateY(0) rotate(-1.5deg)}50%{transform:translateY(-10px) rotate(1.5deg)}}
h1.h{margin:4px 0 0;font:700 clamp(1.9rem,7.2vw,5.2rem)/1.12 var(--fd);letter-spacing:.07em;filter:drop-shadow(0 3px 10px rgba(10,19,34,.75)) drop-shadow(0 0 28px rgba(255,140,185,.45))}
h1.h .wd{display:inline-block;white-space:nowrap;margin:0 .14em}
h1.h .ch{display:inline-block;background:linear-gradient(100deg,#fff6e0 5%,var(--gold) 36%,var(--pk) 70%,#fff0f6 100%);background-size:220% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;animation:rise .9s cubic-bezier(.2,.9,.3,1) both,shine 6s linear infinite;animation-delay:calc(.25s + var(--i)*.045s),0s}
@keyframes rise{from{opacity:0;transform:translateY(60px) rotate(8deg);filter:blur(10px)}}
@keyframes shine{to{background-position:-220% 0}}
.hero .lead{max-width:56ch;color:#ecd9e3;line-height:1.75;margin:0}
.hero .up{animation:fadeup 1s ease both;animation-delay:var(--d,.2s)}
@keyframes fadeup{from{opacity:0;transform:translateY(24px)}}
/* bloom svg animation */
.bloom{overflow:visible}
.bloom .pt{transform-box:view-box;transform-origin:0 0;transform:scale(0);animation:open 1.6s cubic-bezier(.2,1.4,.35,1) forwards;animation-delay:calc(.2s + var(--i)*.18s)}
@keyframes open{0%{transform:scale(0)}100%{transform:scale(1)}}
.bloom .spin{transform-origin:0 0;animation:turn 40s linear infinite}
@keyframes turn{to{transform:rotate(360deg)}}
/* tiers */
.sponsors{position:relative;padding:40px 0 30px}
.tier{padding:64px 0 10px}
.th{text-align:center;margin-bottom:38px}
.th h2{margin:0 0 10px;font:700 clamp(1.35rem,3.6vw,2.3rem)/1.2 var(--fd);letter-spacing:.12em;text-wrap:balance;background:linear-gradient(100deg,#fff2d8,var(--gold) 40%,var(--pk) 85%);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 16px rgba(255,150,190,.35))}
.th p{margin:0 auto;color:#ecd2e2;max-width:52ch;font:italic 400 clamp(1rem,2vw,1.28rem)/1.6 var(--fs);letter-spacing:.07em}
.div{display:flex;align-items:center;justify-content:center;gap:14px;margin:18px auto 14px;max-width:420px}
.div i{flex:1;height:1px;background:linear-gradient(90deg,transparent,var(--gold) 55%,var(--pk2));transform:scaleX(0);transition:transform 1.3s cubic-bezier(.2,.9,.3,1) .2s}
.div i:last-child{background:linear-gradient(270deg,transparent,var(--gold) 55%,var(--pk2));transform-origin:0 50%}.div i:first-child{transform-origin:100% 50%}
.div svg{width:46px;height:46px;filter:drop-shadow(0 0 9px rgba(255,150,190,.55));transform:scale(0) rotate(-180deg);transition:transform 1.1s cubic-bezier(.2,1.4,.35,1) .5s}
.th.in .div i{transform:none}.th.in .div svg{transform:none}
.div .bloom .pt{animation:none;transform:scale(1)}.div .bloom .spin{animation-duration:14s}
.sgrid{display:flex;flex-wrap:wrap;justify-content:center;gap:20px;perspective:1000px}
.sc{flex:0 1 var(--w);min-width:min(100%,240px)}
.xl{--w:540px;--h:230px}.lg{--w:calc(25% - 15px);--h:160px}.md{--w:300px;--h:150px}
@media(max-width:900px){.lg{--w:calc(50% - 10px)}}@media(max-width:600px){.lg,.md,.xl{--w:100%}}
.pl{position:relative;display:grid;place-items:center;gap:8px;height:var(--h);padding:22px;text-align:center;text-decoration:none;overflow:hidden;border-radius:44px 8px 44px 8px;
  background:linear-gradient(145deg,#fff8ee,var(--cream));color:var(--navy);border:1px solid rgba(255,255,255,.6);box-shadow:0 14px 40px rgba(0,0,0,.35),0 0 0 1px var(--ln);
  transform:rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg));transition:transform .18s ease-out,box-shadow .4s;--mx:50%;--my:50%}
.pl::before{content:'';position:absolute;inset:0;background:radial-gradient(260px circle at var(--mx) var(--my),rgba(255,120,170,.3),transparent 65%);opacity:0;transition:opacity .4s}
.pl::after{content:'';position:absolute;top:0;bottom:0;width:40%;left:-60%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.75),transparent);transform:skewX(-18deg)}
.pl:hover{box-shadow:0 24px 60px rgba(255,95,158,.35),0 0 0 1px rgba(255,158,196,.7)}
.pl:hover::before{opacity:1}.pl:hover::after{left:130%;transition:left .9s ease}
.pl img{max-height:calc(var(--h) - 70px);max-width:82%;width:auto;object-fit:contain;position:relative;transition:transform .5s cubic-bezier(.2,1.3,.4,1)}
.pl:hover img{transform:scale(1.08) translateZ(30px)}
.pl .nm{position:relative;font:700 clamp(1rem,2vw,1.3rem)/1.25 var(--fd);letter-spacing:.09em}
.pl small{position:relative;font:600 10px/1 var(--fb);letter-spacing:.2em;text-transform:uppercase;color:#9a5a75;opacity:.75}
.pl.slot{background:linear-gradient(145deg,rgba(255,255,255,.07),rgba(255,255,255,.02));color:var(--mu);border:1.5px dashed rgba(255,158,196,.4);box-shadow:none;backdrop-filter:blur(8px)}
.pl.slot::before{background:radial-gradient(260px circle at var(--mx) var(--my),rgba(255,158,196,.22),transparent 65%)}
.pl.slot::after{display:none}.pl.slot:hover{box-shadow:0 0 50px rgba(255,95,158,.25);border-color:var(--pk)}
.bud{width:54px;height:54px;position:relative;transition:transform .7s cubic-bezier(.2,1.4,.35,1)}
.bud .pt{transform:scale(.3);transform-box:view-box;transform-origin:0 0;transition:transform .8s cubic-bezier(.2,1.4,.35,1);transition-delay:calc(var(--i)*.06s);animation:none}
.bud .spin{animation:none}
.pl.slot:hover .bud{transform:rotate(90deg) scale(1.12)}.pl.slot:hover .bud .pt{transform:scale(1)}
.pl.slot b{font:700 11px/1 var(--fb);letter-spacing:.2em;text-transform:uppercase;color:var(--tx)}
/* marquee */
.past{padding:70px 0 20px;overflow:hidden}
.mq{display:flex;overflow:hidden;-webkit-mask-image:linear-gradient(90deg,transparent,#000 10%,#000 90%,transparent);mask-image:linear-gradient(90deg,transparent,#000 10%,#000 90%,transparent);margin-top:14px}
.mq ul{flex:none;display:flex;gap:14px;list-style:none;margin:0;padding:0 7px;animation:run 38s linear infinite}
.mq.rev ul{animation-direction:reverse;animation-duration:46s}
.mq:hover ul{animation-play-state:paused}
@keyframes run{to{transform:translateX(-100%)}}
.mq li{white-space:nowrap;padding:14px 26px;border-radius:999px;border:1px solid var(--ln);background:rgba(255,255,255,.04);font:600 12px/1 var(--fb);letter-spacing:.16em;text-transform:uppercase;color:#e7d3de;display:flex;gap:12px;align-items:center;transition:.3s}
.mq li::before{content:'✿';color:var(--pk)}
.mq li:hover{background:rgba(255,158,196,.14);border-color:var(--pk);color:#fff}
/* CTA */
.cta-sec{padding:90px 0 100px}
.join{position:relative;overflow:hidden;text-align:center;padding:clamp(40px,7vw,84px) 22px;border-radius:56px 12px 56px 12px;border:1px solid var(--ln);
  background:radial-gradient(ellipse at 50% 0,rgba(255,120,170,.28),transparent 65%),linear-gradient(145deg,rgba(255,255,255,.08),rgba(255,255,255,.02));backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px)}
.join .bloom{width:clamp(130px,20vw,190px);margin:0 auto 10px;display:block}
.join .bloom .pt{animation:none;transform:scale(calc(.12 + var(--bp,0)*.88));transition:transform .2s linear}
.join .bloom .spin{animation:none;transform:rotate(calc(var(--bp,0)*200deg))}
.join h2{margin:0 0 14px;font:700 clamp(1.5rem,4.4vw,2.8rem)/1.2 var(--fd);letter-spacing:.08em;text-wrap:balance;background:linear-gradient(100deg,#fff2d8,var(--gold) 40%,var(--pk) 85%);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 18px rgba(255,150,190,.35))}
.join p{margin:0 auto 26px;color:var(--mu);max-width:54ch;line-height:1.75}
.row{display:flex;flex-wrap:wrap;gap:12px;justify-content:center}
footer{border-top:1px solid var(--ln);padding:40px 0 28px;background:var(--s1);text-align:center;color:var(--mu);font-size:13px}
footer .fl{display:flex;flex-wrap:wrap;justify-content:center;gap:6px 22px;margin:14px 0 18px}footer a{text-decoration:none}footer a:hover{color:#fff}
/* 3D waterfall canvas (drawn in artwork coordinates, screen-blended) */
#wfcv{position:absolute;left:29%;top:55%;width:42%;height:27%;pointer-events:none;mix-blend-mode:screen}

/* HD sky layer: birds, flare, glints (one canvas) + god-rays */
.stage{will-change:transform;transform:translate3d(0,0,0) scale(1.035)}
#skyfx{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.rayw{position:absolute;left:84.7%;top:46.5%;width:95%;aspect-ratio:1;translate:-50% -50%;clip-path:inset(0 0 50% 0);pointer-events:none;mix-blend-mode:screen}
.rays{position:absolute;inset:0;opacity:.5;background:repeating-conic-gradient(from 0deg,rgba(255,205,160,0) 0 6deg,rgba(255,205,160,.13) 8deg 9deg,rgba(255,205,160,0) 11deg 16deg);-webkit-mask-image:radial-gradient(circle,#000 0,transparent 60%);mask-image:radial-gradient(circle,#000 0,transparent 60%);animation:rayspin 120s linear infinite,raypulse 7s ease-in-out infinite}
@keyframes rayspin{to{transform:rotate(360deg)}}@keyframes raypulse{50%{opacity:.8}}

/* ===== DAY / NIGHT (colour grade only — layout & design unchanged) ===== */
.mode{flex:none;width:42px;height:42px;border-radius:50%;border:1px solid var(--ln);background:rgba(255,255,255,.06);color:#fff;cursor:pointer;display:grid;place-items:center;transition:transform .3s,background .3s}
.mode:hover{transform:rotate(18deg) scale(1.06);background:rgba(255,255,255,.14)}.mode svg{width:20px;height:20px}.mode .sn{display:none}
html[data-mode=night] .mode .sn{display:block}html[data-mode=night] .mode .mn{display:none}
@media(max-width:1020px){.mode{margin-left:auto}}
.nt,.moon,#litfx{position:absolute;inset:0;pointer-events:none}
.tag{z-index:5}.nt{z-index:3}
.nt1{background:#2f55d6;mix-blend-mode:color;opacity:calc(var(--nt,0)*.97)}
.nt2{background:#13235f;mix-blend-mode:multiply;opacity:calc(var(--nt,0)*.9)}
.nsun{z-index:4;inset:auto;left:84.7%;top:46.5%;width:17%;aspect-ratio:1;translate:-50% -50%;border-radius:50%;background:radial-gradient(circle,rgba(8,18,60,.92),rgba(8,18,60,.55) 42%,transparent 72%);opacity:var(--nt,0)}
.moon{z-index:6;inset:auto;left:67.7%;top:16.2%;width:13%;aspect-ratio:1;translate:-50% -50%;mix-blend-mode:screen;background:radial-gradient(circle,rgba(235,244,255,.7),rgba(150,180,255,.28) 30%,transparent 62%);opacity:var(--nt,0)}
#litfx{width:100%;height:100%;z-index:6}
.rayw{opacity:calc(1 - var(--nt,0))}
.lid{position:absolute;left:32.7%;top:30%;width:3%;aspect-ratio:2/1;translate:-50% -50%;rotate:26deg;opacity:clamp(0,calc((var(--nt,0) - .35)*2.5),1);pointer-events:none}
.zz{position:absolute;left:37.6%;top:34%;z-index:6;pointer-events:none;opacity:clamp(0,calc((var(--nt,0) - .6)*2.5),1)}
.zz i{position:absolute;left:0;top:0;font:italic 700 1.7cqw/1 var(--fs);color:#d3e2ff;text-shadow:0 0 .7cqw rgba(120,160,255,.95);opacity:0;animation:zz 5.4s ease-in-out infinite;animation-delay:calc(var(--k)*1.8s)}
@keyframes zz{0%{opacity:0;transform:translate(0,0) scale(.6)}20%{opacity:.95}100%{opacity:0;transform:translate(3.4cqw,-4.8cqw) scale(1.5) rotate(12deg)}}
@keyframes bodyZ{0%,100%{transform:perspective(1500px) rotateY(-1deg) scale(1) translate3d(0,0,0)}50%{transform:perspective(1500px) rotateY(1deg) scale(1.01) translate3d(0,-.35%,0)}}
@keyframes headZ{0%,100%{transform:perspective(1300px) rotateZ(3.4deg) rotateX(2deg) translate3d(.1%,.95%,0)}50%{transform:perspective(1300px) rotateZ(2.5deg) rotateX(1deg) scale(1.006) translate3d(.1%,.55%,0)}}
@keyframes tailZ{0%,100%{transform:perspective(1200px) rotateZ(-1.2deg)}50%{transform:perspective(1200px) rotateZ(1.4deg) translate3d(.1%,-.1%,0)}}
html[data-mode=night] .dmove{animation:bodyZ 9s ease-in-out infinite}
html[data-mode=night] .dp.h{animation:headZ 7.5s ease-in-out infinite}
html[data-mode=night] .dp.t{animation:tailZ 10s ease-in-out infinite}
html[data-mode=night] .eye{animation:none;opacity:0}
html[data-mode=night] .mist{animation-duration:13s}
html[data-mode=night] #sparks{opacity:.3}
html[data-mode=night] .tag text{fill:#d3e2ff;stroke:#d3e2ff;filter:drop-shadow(0 0 5px rgba(130,170,255,.8)) drop-shadow(0 0 14px rgba(80,120,255,.5))}
html[data-mode=night]{--bg:#050b1f;--s1:#07122e;--cream:#c9d8fb;--gold:#b9ceff;--pk:#8fb0ff;--pk2:#4f78ff;--cy:#6fd3ff;--vi:#6a5cff;--tx:#e9f0ff;--mu:#8da2d0;--ln:rgba(125,165,255,.24);--navy:#0d1b3e}
html[data-mode=night] .nav{background:rgba(5,11,31,.28)}html[data-mode=night] .nav.sc{background:rgba(5,11,31,.9)}
@media(max-width:1020px){html[data-mode=night] .links{background:rgba(5,11,31,.97)}}
html[data-mode=night] .hero::before{background:linear-gradient(180deg,rgba(4,9,28,.62),rgba(4,9,28,.12) 38%,rgba(4,9,28,.4) 72%,var(--bg))}
html[data-mode=night] .sunrise{background:radial-gradient(circle,rgba(90,130,255,.3),rgba(60,90,230,.14) 45%,transparent 70%)}
html[data-mode=night] .bokeh{background:radial-gradient(ellipse 50% 40% at 8% 6%,rgba(80,120,255,.18),transparent 70%),radial-gradient(ellipse 45% 38% at 94% 10%,rgba(90,130,255,.15),transparent 70%),radial-gradient(ellipse 70% 30% at 50% 108%,rgba(70,110,255,.14),transparent 70%)}
html[data-mode=night] .brn{filter:hue-rotate(-118deg) saturate(.85) brightness(.82) drop-shadow(0 6px 18px rgba(90,130,255,.3))}
html[data-mode=night] h1.h{filter:drop-shadow(0 3px 10px rgba(4,9,28,.8)) drop-shadow(0 0 28px rgba(100,140,255,.5))}
html[data-mode=night] h1.h .ch{background-image:linear-gradient(100deg,#f1f6ff 5%,var(--gold) 36%,var(--pk) 70%,#f4f8ff 100%)}
html[data-mode=night] .th h2,html[data-mode=night] .join h2{background-image:linear-gradient(100deg,#eef4ff,var(--gold) 40%,var(--pk) 85%);filter:drop-shadow(0 0 16px rgba(100,140,255,.4))}
html[data-mode=night] .script{text-shadow:0 2px 14px rgba(4,9,28,.7),0 0 24px rgba(110,150,255,.4)}
html[data-mode=night] .hero .lead{color:#cdd9f5}html[data-mode=night] .th p{color:#cfdbf7}html[data-mode=night] .mq li{color:#d3def7}
html[data-mode=night] .btn.p{color:#04102e;box-shadow:0 10px 30px rgba(79,120,255,.35)}html[data-mode=night] .btn.p:hover{box-shadow:0 14px 40px rgba(79,120,255,.55)}
html[data-mode=night] .pl{background:linear-gradient(145deg,#eef3ff,var(--cream));box-shadow:0 14px 40px rgba(0,0,0,.45),0 0 0 1px var(--ln)}
html[data-mode=night] .pl::before{background:radial-gradient(260px circle at var(--mx) var(--my),rgba(79,120,255,.3),transparent 65%)}
html[data-mode=night] .pl:hover{box-shadow:0 24px 60px rgba(79,120,255,.38),0 0 0 1px rgba(143,176,255,.7)}
html[data-mode=night] .pl small{color:#5a6fa5}
html[data-mode=night] .pl.slot{background:linear-gradient(145deg,rgba(255,255,255,.07),rgba(255,255,255,.02));border-color:rgba(143,176,255,.4);box-shadow:none}
html[data-mode=night] .pl.slot::before{background:radial-gradient(260px circle at var(--mx) var(--my),rgba(143,176,255,.22),transparent 65%)}
html[data-mode=night] .pl.slot:hover{box-shadow:0 0 50px rgba(79,120,255,.3)}
html[data-mode=night] .mq li:hover{background:rgba(143,176,255,.14)}
html[data-mode=night] .join{background:radial-gradient(ellipse at 50% 0,rgba(79,120,255,.3),transparent 65%),linear-gradient(145deg,rgba(255,255,255,.08),rgba(255,255,255,.02))}
html[data-mode=night] .bp{background:linear-gradient(135deg,#dfe8ff,var(--pk2))}
html[data-mode=night] .div svg{filter:drop-shadow(0 0 9px rgba(110,150,255,.6))}
body,.nav,.pl,.join,footer,.mq li,.btn{transition:background-color .9s,border-color .9s,color .9s,transform .25s,box-shadow .4s}
/* night: sleeping dragon dreams - dream bubbles drift up from its head, a tiny blossom turning inside the last one */
.dr{position:absolute;left:35.5%;top:24%;z-index:6;pointer-events:none;opacity:clamp(0,calc((var(--nt,0) - .6)*2.5),1)}
.dr i{position:absolute;display:grid;place-items:center;border-radius:50%;border:1px solid rgba(205,222,255,.6);background:radial-gradient(circle at 32% 28%,rgba(255,255,255,.4),rgba(150,180,255,.13) 60%,rgba(120,150,255,.05));box-shadow:0 0 .5cqw rgba(150,180,255,.3);opacity:0;animation:drm 9s ease-in-out infinite;animation-delay:var(--d)}
.dr i b{font:400 1.7cqw/1 var(--fd);color:#d6e4ff;text-shadow:0 0 .6cqw rgba(130,165,255,.9);animation:drspin 9s linear infinite;animation-delay:var(--d)}
@keyframes drm{0%{opacity:0;transform:scale(.3) translateY(.8cqw)}14%,68%{opacity:1;transform:scale(1) translateY(0)}86%,100%{opacity:0;transform:scale(1.1) translateY(-.9cqw)}}
@keyframes drspin{to{transform:rotate(360deg)}}
/* full moon (night only): cold, hazy, slightly wrong - flickers, wisps of cloud and bats cross it */
.fm{position:absolute;left:67.7%;top:16.2%;width:7.6%;aspect-ratio:1;translate:-50% -50%;z-index:6;pointer-events:none;opacity:clamp(0,calc((var(--nt,0) - .45)*2.2),1)}
.fm .d{position:absolute;inset:0;border-radius:50%;overflow:hidden;background:radial-gradient(circle at 36% 32%,#fffef4 0,#eef0ff 36%,#d2d9f1 68%,#a6b3dc 100%);
  box-shadow:0 0 1.1cqw .2cqw rgba(214,226,255,.8),0 0 4cqw 1.1cqw rgba(130,160,255,.38),0 0 12cqw 3cqw rgba(90,120,240,.2);animation:mflick 9s linear infinite}
.fm .d::before{content:'';position:absolute;inset:0;border-radius:50%;filter:blur(.1cqw);
  background:radial-gradient(circle at 30% 38%,rgba(110,125,175,.4) 0 9%,transparent 11%),radial-gradient(circle at 58% 26%,rgba(110,125,175,.3) 0 6%,transparent 8%),radial-gradient(circle at 64% 62%,rgba(105,120,170,.36) 0 11%,transparent 13%),radial-gradient(circle at 40% 74%,rgba(110,125,175,.28) 0 5%,transparent 7%),radial-gradient(ellipse at 52% 45%,rgba(135,150,200,.25),transparent 62%)}
.fm .d::after{content:'';position:absolute;inset:0;border-radius:50%;background:radial-gradient(circle at 70% 75%,rgba(30,45,110,.28),transparent 60%)}
.fm .ring{position:absolute;inset:-14%;border-radius:50%;border:1px solid rgba(190,208,255,.28);animation:mring 6s ease-in-out infinite}
.fm .wp{position:absolute;left:-120%;width:300%;height:30%;border-radius:50%;background:radial-gradient(ellipse,rgba(5,12,48,.6),transparent 70%);filter:blur(.35cqw);animation:wisp 24s linear infinite;animation-delay:var(--w,0s)}
@keyframes wisp{0%{transform:translateX(-12%);opacity:0}10%,85%{opacity:1}100%{transform:translateX(52%);opacity:0}}
@keyframes mring{0%,100%{transform:scale(.96);opacity:.25}50%{transform:scale(1.08);opacity:.7}}
@keyframes mflick{0%,100%{opacity:1}44%{opacity:.97}46%{opacity:.84}48%{opacity:1}52%{opacity:.93}54%{opacity:1}}
/* day<->night: the dragon lifts into 3D while the light changes (body turns, head leans forward, tail swings back, soft depth shadow). Only active mid-transition. */
.stage.trans{perspective:1800px;perspective-origin:20% 45%}
.stage.trans .dmove{perspective:1400px;perspective-origin:22% 45%;rotate:0 1 0 calc(var(--tr,0)*-13deg);translate:calc(var(--tr,0)*1%) calc(var(--tr,0)*var(--dr,1)*.9%);scale:calc(1 + var(--tr,0)*.03);filter:drop-shadow(0 calc(var(--tr,0)*1.3cqw) calc(var(--tr,0)*1.7cqw) rgba(8,12,48,.55))}
.stage.trans .dp.h{rotate:1 1 0 calc(var(--tr,0)*9deg);translate:calc(var(--tr,0)*1.5%) calc(var(--tr,0)*var(--dr,1)*1%);scale:calc(1 + var(--tr,0)*.05)}
.stage.trans .dp.t{rotate:0 1 0 calc(var(--tr,0)*20deg);translate:calc(var(--tr,0)*-1.4%) 0;scale:calc(1 - var(--tr,0)*.025)}
/* click-burst petals */
.bp{position:fixed;z-index:130;width:12px;height:16px;border-radius:0 100% 0 100%;pointer-events:none;background:linear-gradient(135deg,#ffd5e5,var(--pk2));animation:burst 1.1s cubic-bezier(.15,.8,.3,1) forwards}
@keyframes burst{to{transform:translate(var(--x),var(--y)) rotate(var(--r));opacity:0}}
@media(prefers-reduced-motion:reduce){.brn{animation:none!important}html{scroll-behavior:auto}.js .rv{opacity:1;transform:none}#petalfx{display:none}#wfcv,#skyfx,.rayw{display:none}.zz i{animation:none}.stage{transform:none}*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;transition-delay:0s!important}.bloom .pt{transform:scale(1)}}
</style>
</head>
